def compute_order_amount(on_hand_inventory, pipeline_orders):
    import math

    demand_scale = 20.0  # OPT_PARAM: {'initial': 20.0, 'min': 0.1, 'max': 500.0, 'type': 'float'}
    logistic_slope = 1.0  # OPT_PARAM: {'initial': 1.0, 'min': 0.1, 'max': 10.0, 'type': 'float'}
    stockout_threshold = 0.3  # OPT_PARAM: {'initial': 0.3, 'min': 0.01, 'max': 0.99, 'type': 'float'}
    max_additional_order = 200  # OPT_PARAM: {'initial': 200, 'min': 10, 'max': 1000, 'type': 'int'}

    L = len(pipeline_orders)
    if L <= 0:
        L = 1

    base_inventory_position = on_hand_inventory + sum(pipeline_orders)

    def pseudo_stockout_prob(total_inventory):
        avg_inv = total_inventory / float(L)
        x = (avg_inv - demand_scale) / max(demand_scale, 1e-6)
        return 1.0 / (1.0 + math.exp(logistic_slope * x))

    best_z = max_additional_order
    for z in range(0, max_additional_order + 1):
        total_inventory = base_inventory_position + z
        prob_stockout = pseudo_stockout_prob(total_inventory)
        if prob_stockout <= stockout_threshold:
            best_z = z
            break

    order_amount = float(best_z)
    return order_amount
